159	json OpenAIResponsesAgent::initial_input(const AgentRequest& request) const
160	{
161	    json input = json::array();
162	    for (const auto& message : request.conversation) {
163	        if (message.call_id.empty()) {
164	            if (message.issue_context.empty())
165	                input.push_back(json{{"role", message.role}, {"content", message.text}});
166	            else
167	                input.push_back(json{{"role", message.role},
168	                                     {"content", json::array({text_part(message.text),
169	                                                              text_part(tagged("print_issue", message.issue_context))})}});
170	            continue;
171	        }
172	        // A call from an earlier turn, replayed for this stateless request.
173	        // Its call_id pairs it with its output. The item id the service gave
174	        // the call is not sent: with store:false it names nothing kept.
175	        input.push_back(json{{"type", "function_call"}, {"call_id", message.call_id}, {"name", message.tool},
176	                             {"arguments", message.arguments_json}});
177	        input.push_back(json{{"type", "function_call_output"}, {"call_id", message.call_id}, {"output", message.output_json}});
178	    }
179	    if (request.purpose == AgentRequest::Purpose::ConversationTitle)
180	        return input;
181	    // A turn the app started, after one of its own notes: nothing was said,
182	    // and an empty user message would read as the person saying nothing.
183	    if (request.user_text.empty() && request.issue_context.empty() && request.attachments.empty() &&
184	        !request.session.include_workspace)
185	        return input;
186	
187	    // One part per kind of content: the person's words exactly as typed, then
188	    // the app's data, each in its own tag, then the attachments.
189	    json content = json::array();
190	    if (!request.user_text.empty())
191	        content.push_back(text_part(request.user_text));
192	    if (!request.issue_context.empty())
193	        content.push_back(text_part(tagged("print_issue", request.issue_context)));
194	    if (request.session.include_workspace)
195	        content.push_back(text_part(tagged("workspace", workspace_json(request).dump())));
196	    std::ostringstream attachments;
197	    for (const auto& attachment : request.attachments) {
198	        if (attachments.tellp() > 0)
199	            attachments << "\n";
200	        attachments << "Attachment " << attachment.id << ": " << attachment.name << " [" << attachment.kind << "]";
201	        if (!attachment.summary.empty())
202	            attachments << " — " << attachment.summary;
203	        if (!attachment.text.empty())
204	            attachments << "\n<attachment id=\"" << attachment.id << "\">\n" << attachment.text << "\n</attachment>";
205	    }
206	    if (attachments.tellp() > 0)
207	        content.push_back(text_part(attachments.str()));
208	    for (const auto& attachment : request.attachments) {
209	        if (attachment.bytes.empty())
210	            continue;
211	        const std::string mime = attachment.mime.empty() ? "application/octet-stream" : attachment.mime;
212	        const std::string data_url = "data:" + mime + ";base64," + base64_encode(attachment.bytes);
213	        if (attachment.kind == "image")
214	            content.push_back(json{{"type", "input_image"}, {"image_url", data_url}});
215	        else if (attachment.kind == "pdf")
216	            content.push_back(json{{"type", "input_file"}, {"filename", attachment.name}, {"file_data", data_url}});
217	    }
218	    input.push_back(json{{"role", "user"}, {"content", std::move(content)}});
219	    return input;
220	}
