240	bool OpenAIResponsesAgent::start(const AgentRequest& request)
241	{
242	    if (!ready() || m_busy)
243	        return false;
244	    m_input_history = json::array();
245	    m_pending_call_id.clear();
246	    m_waiting_for_tool = false;
247	    m_request_id = request.request_id;
248	    m_request_sequence = 0;
249	    m_rejected_calls = 0;
250	    m_title_request = request.purpose == AgentRequest::Purpose::ConversationTitle;
251	    m_session       = request.session;
252	    m_allow_import = std::any_of(request.attachments.begin(), request.attachments.end(),
253	                                 [](const AgentAttachmentContext& attachment) { return attachment.importable; });
254	    return post(initial_input(request));
255	}
