257	bool OpenAIResponsesAgent::continue_after_tool(const AgentToolResult& result)
258	{
259	    if (!m_busy || !m_waiting_for_tool || result.call_id != m_pending_call_id)
260	        return false;
261	    json input = m_input_history;
262	    input.push_back(json{{"type", "function_call_output"}, {"call_id", result.call_id}, {"output", result.output_json}});
263	    // A function result is text only; the picture follows it as an image input.
264	    if (result.image)
265	        input.push_back(json{{"role", "user"},
266	                             {"content", json::array({json{{"type", "input_text"}, {"text", "The image returned by call " + result.call_id + "."}},
267	                                                      json{{"type", "input_image"},
268	                                                           {"image_url", "data:" + result.image->mime_type + ";base64," + result.image->base64}}})}});
269	    m_waiting_for_tool = false;
270	    m_pending_call_id.clear();
271	    return post(std::move(input));
272	}
273	
274	bool OpenAIResponsesAgent::post(json input)
275	{
276	    m_sse_buffer.clear();
277	    m_terminal_seen = false;
278	    m_busy = true;
279	    AgentHttpRequest request;
280	    request.url = m_config.endpoint;
281	    request.authorization = "Bearer " + m_config.api_key;
282	    request.idempotency_key = m_request_id + "-request-" + std::to_string(++m_request_sequence);
283	    // store:false requests are stateless. Retain the complete turn input,
284	    // including user context and earlier tool results, for each continuation.
285	    m_input_history = input;
286	    request.body = request_body(std::move(input)).dump();
287	    const std::uint64_t generation = ++m_http_generation;
288	    if (!m_transport->post(std::move(request), [this, generation](AgentHttpEvent event) {
289	            accept_http(generation, std::move(event));
290	        })) {
291	        m_busy = false;
292	        return false;
293	    }
294	    return true;
295	}
