297	void OpenAIResponsesAgent::accept_http(std::uint64_t generation, AgentHttpEvent event)
298	{
299	    std::lock_guard<std::mutex> lock(m_mutex);
300	    m_http_events.push_back(QueuedHttpEvent{generation, std::move(event)});
301	}
302	
303	void OpenAIResponsesAgent::parse_sse_frame(const std::string& frame)
304	{
305	    std::string payload;
306	    std::istringstream lines(frame);
307	    std::string line;
308	    while (std::getline(lines, line)) {
309	        if (!line.empty() && line.back() == '\r')
310	            line.pop_back();
311	        if (line.rfind("data:", 0) == 0) {
312	            std::string part = line.substr(5);
313	            if (!part.empty() && part.front() == ' ')
314	                part.erase(part.begin());
315	            if (!payload.empty())
316	                payload += '\n';
317	            payload += part;
318	        }
319	    }
320	    if (payload.empty() || payload == "[DONE]")
321	        return;
322	    const json event = json::parse(payload, nullptr, false);
323	    if (!event.is_object()) {
324	        fail(AgentError{"malformed_response", "The Agent service returned an unreadable streaming response.", false});
325	        return;
326	    }
327	    const std::string type = event.value("type", "");
328	    if (type == "response.output_text.delta" && event.contains("delta") && event["delta"].is_string())
329	        m_events.push_back(AgentEvent::delta(event["delta"].get<std::string>()));
330	    else if (type == "response.completed" && event.contains("response"))
331	        finish_response(event["response"]);
332	    else if (type == "response.incomplete")
333	        fail(AgentError{"incomplete_response", "The Agent service stopped before finishing its response.", true});
334	    else if (type == "response.failed" || type == "error")
335	        fail(AgentError{"agent_service_error", "The Agent service could not complete the response.", true});
336	}
337	
338	void OpenAIResponsesAgent::finish_response(const json& response)
339	{
340	    if (m_terminal_seen)
341	        return;
342	    m_terminal_seen = true;
343	    if (!response.is_object() || !response.contains("output") || !response["output"].is_array()) {
344	        fail(AgentError{"malformed_response", "The Agent service response did not contain valid output.", false});
345	        return;
346	    }
347	    const auto& output = response["output"];
348	    m_input_history.insert(m_input_history.end(), output.begin(), output.end());
349	    if (m_config.usage_listener && response.contains("usage") && response["usage"].is_object()) {
350	        const json& usage = response["usage"];
351	        AgentUsage   reported;
352	        reported.input  = usage.value("input_tokens", std::uint64_t{0});
353	        reported.output = usage.value("output_tokens", std::uint64_t{0});
354	        reported.total  = usage.value("total_tokens", std::uint64_t{0});
355	        if (usage.contains("input_tokens_details") && usage["input_tokens_details"].is_object())
356	            reported.cached_input = usage["input_tokens_details"].value("cached_tokens", std::uint64_t{0});
357	        m_config.usage_listener(reported);
358	    }
359	    for (const json& item : output) {
360	        if (!item.is_object() || item.value("type", "") != "function_call")
361	            continue;
362	        const std::string call_id = item.value("call_id", "");
363	        ToolRequest request{item.value("name", ""), item.value("arguments", "{}")};
364	        const ToolDefinition* definition = ToolRegistry::instance().find(request.tool);
365	        const bool available = !m_title_request && definition != nullptr && available_in_app(*definition, m_allow_import, m_session.tool_names);
366	        ToolValidationResult validation;
367	        if (available)
368	            validation = ToolRegistry::instance().validate_call(*definition, request.arguments_json);
369	        // A call to no tool of this turn, or with arguments that miss the
370	        // tool's contract, never reaches a card. The model gets the refusal as
371	        // that call's result and may correct it, a bounded number of times
372	        // per turn.
373	        constexpr unsigned kRejectedCallLimit = 2;
374	        if ((!available || !validation.valid()) && m_config.refusal_listener)
375	            m_config.refusal_listener(request.tool, request.arguments_json, available ? validation.error->code : "unknown_tool");
376	        if (!call_id.empty() && !m_title_request && (!available || !validation.valid()) &&
377	            m_rejected_calls < kRejectedCallLimit) {
378	            ++m_rejected_calls;
379	            json error = available ?
380	                json{{"code", validation.error->code},
381	                     {"message", validation.error->message +
382	                                     " Nothing was queued. Check the arguments against this tool's parameters and call it again."}} :
383	                json{{"code", "unknown_tool"},
384	                     {"message", "There is no tool named \"" + request.tool + "\" here. Nothing was queued. Use one of the listed tools."}};
385	            json refusal{{"state", "failed"}, {"error", std::move(error)}};
386	            json input = m_input_history;
387	            input.push_back(json{{"type", "function_call_output"}, {"call_id", call_id}, {"output", refusal.dump()}});
388	            if (!post(std::move(input)))
389	                fail(AgentError{"agent_continuation_failed", "The Agent could not be told its tool arguments were invalid.", true});
390	            return;
391	        }
392	        if (call_id.empty() || !available || !validation.valid()) {
393	            fail(AgentError{"malformed_tool_call", "The Agent returned an invalid tool call.", false});
394	            return;
395	        }
396	        request.arguments_json = std::move(validation.arguments_json);
397	        m_pending_call_id = call_id;
398	        m_waiting_for_tool = true;
399	        AgentToolCall call{call_id, std::move(request), true};
400	        m_events.push_back(AgentEvent::tool_call(std::move(call)));
401	        return;
402	    }
403	    m_busy = false;
404	    m_events.push_back(AgentEvent::completed());
405	}
406	
407	void OpenAIResponsesAgent::parse_available()
408	{
409	    std::deque<QueuedHttpEvent> incoming;
410	    {
411	        std::lock_guard<std::mutex> lock(m_mutex);
412	        incoming.swap(m_http_events);
413	    }
414	    for (QueuedHttpEvent& queued : incoming) {
415	        if (queued.generation != m_http_generation)
416	            continue;
417	        AgentHttpEvent& event = queued.event;
418	        if (event.kind == AgentHttpEvent::Kind::Data) {
419	            m_sse_buffer += event.data;
420	            for (;;) {
421	                const std::size_t lf_pos = m_sse_buffer.find("\n\n");
422	                const std::size_t crlf_pos = m_sse_buffer.find("\r\n\r\n");
423	                const bool crlf_first = crlf_pos != std::string::npos &&
424	                                        (lf_pos == std::string::npos || crlf_pos < lf_pos);
425	                const std::size_t pos = crlf_first ? crlf_pos : lf_pos;
426	                if (pos == std::string::npos)
427	                    break;
428	                const std::string frame = m_sse_buffer.substr(0, pos);
429	                m_sse_buffer.erase(0, pos + (crlf_first ? 4 : 2));
430	                parse_sse_frame(frame);
431	            }
432	        } else if (event.kind == AgentHttpEvent::Kind::Error) {
433	            fail(http_error(event.status, event.error));
434	        } else if (!m_terminal_seen) {
435	            // A valid SSE stream may close immediately after its final data
436	            // line without a trailing blank-line delimiter. Consume that
437	            // complete residual frame before classifying the response.
438	            if (!m_sse_buffer.empty()) {
439	                parse_sse_frame(m_sse_buffer);
440	                m_sse_buffer.clear();
441	            }
442	            if (!m_terminal_seen)
443	                fail(AgentError{"malformed_response", "The Agent service ended before a complete response arrived.", true});
444	        }
445	    }
446	}
447	
448	std::optional<AgentEvent> OpenAIResponsesAgent::poll()
449	{
450	    parse_available();
451	    if (m_events.empty())
452	        return std::nullopt;
453	    AgentEvent event = std::move(m_events.front());
454	    m_events.pop_front();
455	    return event;
456	}
457	
458	AgentError OpenAIResponsesAgent::http_error(unsigned status, const std::string& detail) const
459	{
460	    if (status == 401 || status == 403)
461	        return {"invalid_credentials", "The OpenAI API key was rejected. Update the Agent configuration and try again.", false};
462	    if (status == 429)
463	        return {"rate_limited", "The OpenAI service is rate limited. Try again shortly.", true};
464	    if (status >= 500)
465	        return {"service_unavailable", "The OpenAI service is temporarily unavailable.", true};
466	    if (status == 408 || detail.find("timed out") != std::string::npos || detail.find("Timeout") != std::string::npos)
467	        return {"timeout", "The Agent request timed out.", true};
468	    return {"network_error", "The Agent request could not reach the OpenAI service.", true};
469	}
470	
471	void OpenAIResponsesAgent::fail(AgentError error)
472	{
473	    if (!m_busy && m_terminal_seen)
474	        return;
475	    m_busy = false;
476	    m_waiting_for_tool = false;
477	    m_terminal_seen = true;
478	    m_events.push_back(AgentEvent::failed(std::move(error)));
479	}
480	
481	void OpenAIResponsesAgent::cancel()
482	{
483	    if (m_transport)
484	        m_transport->cancel();
485	    ++m_http_generation;
486	    {
487	        std::lock_guard<std::mutex> lock(m_mutex);
488	        m_http_events.clear();
489	    }
490	    m_events.clear();
491	    m_sse_buffer.clear();
492	    m_busy = false;
493	    m_waiting_for_tool = false;
494	    m_terminal_seen = true;
495	}
