42	// What one request cost, as the provider reported it. `cached_input` is the
43	// part of `input` the provider served from its prompt cache, and it is the
44	// number the tool-loading decision rests on: a tools array that stays
45	// byte-identical across a chat should be cached from the second request on,
46	// and a catalog that is not being cached is paid for in full every turn.
47	struct AgentUsage
48	{
49	    std::uint64_t input{0};
50	    std::uint64_t cached_input{0};
51	    std::uint64_t output{0};
52	    std::uint64_t total{0};
