110	enum class AgentEventKind : std::uint8_t { TextDelta, ToolCall, Completed, Failed };
111	
112	struct AgentEvent
113	{
114	    AgentEventKind               kind{AgentEventKind::Completed};
115	    std::string                  text;
116	    std::optional<AgentToolCall> tool;
117	    std::optional<AgentError>    error;
118	
119	    static AgentEvent delta(std::string value)
120	    {
121	        AgentEvent event;
122	        event.kind = AgentEventKind::TextDelta;
123	        event.text = std::move(value);
124	        return event;
125	    }
126	
127	    static AgentEvent tool_call(AgentToolCall value)
128	    {
129	        AgentEvent event;
130	        event.kind = AgentEventKind::ToolCall;
131	        event.tool = std::move(value);
132	        return event;
133	    }
134	
135	    static AgentEvent completed()
136	    {
137	        AgentEvent event;
138	        event.kind = AgentEventKind::Completed;
139	        return event;
140	    }
141	
142	    static AgentEvent failed(AgentError value)
143	    {
144	        AgentEvent event;
145	        event.kind  = AgentEventKind::Failed;
146	        event.error = std::move(value);
147	        return event;
148	    }
149	};
